// Command lathe orchestrates bounded agent work in whatever repo you invoke it from.
package main

import (
	"fmt"
	"os"

	"github.com/tyrelh/lathe/internal/install"
)

const usage = `lathe — a software factory you run from any repo

usage: lathe <command> [args]

commands:
  install    link this repo into each agent's skills directory
  help       show this message

Run install from a checkout of the lathe repo; it links the checkout itself,
so SKILL.md stays discoverable.
`

func main() {
	if len(os.Args) < 2 {
		fmt.Print(usage)
		os.Exit(2)
	}
	switch os.Args[1] {
	case "install":
		cwd, err := os.Getwd()
		if err == nil {
			err = install.Run(cwd, os.Stdout)
		}
		if err != nil {
			fmt.Fprintln(os.Stderr, "lathe install:", err)
			os.Exit(1)
		}
	case "help", "-h", "--help":
		fmt.Print(usage)
	default:
		fmt.Fprintf(os.Stderr, "lathe: unknown command %q\n\n%s", os.Args[1], usage)
		os.Exit(2)
	}
}

// Package install links the lathe repo into each agent's skills directory.
package install

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// skillDirs are the agent skill directories lathe links itself into, relative
// to the user's home directory. A directory that does not exist is skipped.
var skillDirs = []string{".claude/skills", ".codex/skills", ".pi/agent/skills"}

// Run creates (or verifies) a `lathe` symlink in every existing skill
// directory, pointing at repoRoot. It never replaces anything it did not
// create. Progress is written to out.
func Run(repoRoot string, out io.Writer) error {
	repoRoot, err := filepath.Abs(repoRoot)
	if err != nil {
		return err
	}
	if _, err := os.Stat(filepath.Join(repoRoot, "SKILL.md")); err != nil {
		return fmt.Errorf("%s is not a lathe repo (no SKILL.md)", repoRoot)
	}

	home, err := os.UserHomeDir()
	if err != nil {
		return err
	}

	linked := 0
	for _, dir := range skillDirs {
		dir = filepath.Join(home, dir)
		if _, err := os.Stat(dir); err != nil {
			fmt.Fprintf(out, "skip  %s (does not exist)\n", dir)
			continue
		}
		link := filepath.Join(dir, "lathe")
		switch target, err := os.Readlink(link); {
		case err == nil && target == repoRoot:
			fmt.Fprintf(out, "ok    %s\n", link)
			linked++
		case err == nil:
			return fmt.Errorf("%s already links to %s, not %s", link, target, repoRoot)
		default:
			if _, err := os.Lstat(link); err == nil {
				return fmt.Errorf("%s exists and is not a symlink", link)
			}
			if err := os.Symlink(repoRoot, link); err != nil {
				return err
			}
			fmt.Fprintf(out, "link  %s -> %s\n", link, repoRoot)
			linked++
		}
	}
	if linked == 0 {
		return fmt.Errorf("no agent skill directories found under %s", home)
	}

	// A binary that is not on PATH fails identically to a broken skill, so say so.
	if bin := filepath.Join(home, ".local/bin"); !onPath(bin) {
		fmt.Fprintf(out, "warn  %s is not on PATH; agents will not find `lathe`\n", bin)
	}
	return nil
}

func onPath(dir string) bool {
	for _, p := range strings.Split(os.Getenv("PATH"), string(os.PathListSeparator)) {
		if p == dir {
			return true
		}
	}
	return false
}

package install

import (
	"io"
	"os"
	"path/filepath"
	"testing"
)

// repo returns a fake lathe checkout and a fake home with one skill directory.
func repo(t *testing.T) (repoRoot, home string) {
	t.Helper()
	repoRoot = t.TempDir()
	if err := os.WriteFile(filepath.Join(repoRoot, "SKILL.md"), nil, 0o644); err != nil {
		t.Fatal(err)
	}
	home = t.TempDir()
	if err := os.MkdirAll(filepath.Join(home, ".claude/skills"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("HOME", home)
	return repoRoot, home
}

func TestRunLinksAndIsIdempotent(t *testing.T) {
	repoRoot, home := repo(t)
	link := filepath.Join(home, ".claude/skills/lathe")

	for i := 0; i < 2; i++ {
		if err := Run(repoRoot, io.Discard); err != nil {
			t.Fatalf("run %d: %v", i, err)
		}
		if target, err := os.Readlink(link); err != nil || target != repoRoot {
			t.Fatalf("run %d: link = %q, %v; want %q", i, target, err, repoRoot)
		}
	}
	// .codex/skills does not exist in the fake home, so it must be skipped, not created.
	if _, err := os.Stat(filepath.Join(home, ".codex")); !os.IsNotExist(err) {
		t.Fatalf("created a skill directory that did not exist: %v", err)
	}
}

func TestRunRefusesToClobber(t *testing.T) {
	repoRoot, home := repo(t)
	link := filepath.Join(home, ".claude/skills/lathe")

	if err := os.WriteFile(link, []byte("mine"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := Run(repoRoot, io.Discard); err == nil {
		t.Fatal("overwrote a real file")
	}
	if b, _ := os.ReadFile(link); string(b) != "mine" {
		t.Fatalf("file changed: %q", b)
	}

	os.Remove(link)
	if err := os.Symlink(t.TempDir(), link); err != nil {
		t.Fatal(err)
	}
	if err := Run(repoRoot, io.Discard); err == nil {
		t.Fatal("retargeted someone else's symlink")
	}
}

func TestRunRejectsNonRepo(t *testing.T) {
	_, _ = repo(t)
	if err := Run(t.TempDir(), io.Discard); err == nil {
		t.Fatal("accepted a directory with no SKILL.md")
	}
}

